import os
import boto3

def validate_document_fields(payload, config=None):
    config = config or {}
    client = boto3.client('textract', region_name=config.get('region', 'us-east-1'))
    resp = client.analyze_document(Document={'Bytes': payload}, FeatureTypes=['FORMS'])
    blocks = {b['Id']: b for b in resp.get('Blocks', [])}
    kv = {}
    for b in blocks.values():
        if b['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in b['EntityTypes']:
            children = [i for r in b.get('Relationships', []) if r.get('Type') == 'CHILD' for i in r.get('Ids', [])]
            k = ' '.join(blocks[i]['Text'] for i in children)
            for r in b.get('Relationships', []):
                if r.get('Type') == 'VALUE':
                    vals = r.get('Ids', [])
                    kv[k] = max((blocks[v]['Confidence'] for v in vals), default=0)
    req = config.get('required_fields', [])
    thresh = config.get('min_confidence', 0.85)
    result = {'valid': all(f in kv and kv[f] >= thresh for f in req), 'missing': [f for f in req if f not in kv], 'low_confidence': [f for f in req if f in kv and kv[f] < thresh]}
    return result
